item.aggregated_output:
type hit = {
  anchor_offset : int;
  query_start : int;
  doc_start : int;
  doc_end : int;
}

type candidate = {
  doc_id : T.doc_id;
  revision : int;
  contents : string;
  document_hits : int;
  num_hits : int;
  coverage : int;
  mode_offset : int;
  window : T.range;
  range : T.range;
}

let collect_hits db (anchor_norm : normalized) =
  let by_doc = Hashtbl.create 16 in
  let query_shingles = ref 0 in
  iter_shingles ~offset:1 anchor_norm.text (fun anchor_offset shingle ->
      incr query_shingles;
      DB.Shingles.find db (Internal_types.Shingle_str.create shingle)
      |> List.iter (fun (doc_id, (range : T.range)) ->
          let hit =
            {
              anchor_offset;
              query_start = anchor_norm.norm_to_raw.(anchor_offset);
              doc_start = range.start;
              doc_end = range.end_;
            }
          in
          let previous =
            Option.value (Hashtbl.find_opt by_doc doc_id) ~default:[]
          in
          Hashtbl.replace by_doc doc_id (hit :: previous)));
  (!query_shingles, by_doc)

(* Count matched query bytes once, even where overlapping shingles agree. *)
let hit_coverage hits =
  let sorted =
    List.sort (fun a b -> Int.compare a.anchor_offset b.anchor_offset) hits
  in
  let _, coverage =
    List.fold_left
      (fun (end_, total) hit ->
        let next_end = hit.anchor_offset + shingle_length in
        (next_end, total + next_end - max end_ hit.anchor_offset))
      (0, 0) sorted
  in
  coverage

(* Count equal raw displacements. Resolve frequency ties by signed offset,
   independently of hash-table iteration order. Hits are nonempty here. *)
let most_common_offset hits =
  let counts = Hashtbl.create 16 in
  List.iter
    (fun hit ->
      let offset = hit.query_start - hit.doc_start in
      let count = Option.value (Hashtbl.find_opt counts offset) ~default:0 in
      Hashtbl.replace counts offset (count + 1))
    hits;
  let offset, _ =
    Hashtbl.fold
      (fun offset count (best_offset, best_count) ->
        if count > best_count || (count = best_count && offset < best_offset)
        then (offset, count)
        else (best_offset, best_count))
      counts (max_int, 0)
  in
  offset

(* Bytewise alignment may stop inside a UTF-8 character. Realign within the
   narrowed target so the support count describes only the returned bytes. *)
let align_normalized query target =
  let rec align offset target =
    match Util.Smith_waterman.align Util.Smith_waterman.code query target with
    | None -> None
    | Some aligned ->
        let start, end_ =
          Util.Text.safe_range target ~start:aligned.target.start
            ~end_:aligned.target.end_
        in
        if start = aligned.target.start && end_ = aligned.target.end_ then
          Some
            {
              aligned with
              target = { start = offset + start; end_ = offset + end_ };
            }
        else if start >= end_ then None
        else align (offset + start) (String.sub target start (end_ - start))
  in
  align 0 target

let align_candidate ~query ~normalized_query (meta : T.doc_meta) contents hits
    =
  let mode_offset = most_common_offset hits in
  let selected =
    List.filter
      (fun hit ->
        abs (hit.query_start - hit.doc_start - mode_offset)
        <= match_offset_tolerance)
      hits
  in
  let start, end_ =
    List.fold_left
      (fun (start, end_) hit ->
        (min start hit.doc_start, max end_ hit.doc_end))
      (String.length contents, 0)
      selected
  in
  (* Include the query's predicted edges, not just the indexed hits. A name
     change near the beginning can otherwise hide the function header from
     alignment. Local alignment decides which boundary bytes still match. *)
  let start = min start (max 0 (-mode_offset)) in
  let end_ =
    max end_
      (min (String.length contents) (String.length query - mode_offset))
  in
  let window =
    {
      T.start = max 0 (start - shingle_length);
      end_ = min (String.length contents) (end_ + shingle_length);
    }
  in
  let start, end_ =
    Util.Text.safe_range contents ~start:window.start ~end_:window.end_
  in
  let window = { T.start; end_ } in
  (* A normalized shingle may span an arbitrarily long raw whitespace run.
     Enforce the displacement allowance on the whole window before alignment. *)
  let maximum_window =
    String.length query + (2 * match_offset_tolerance) + (2 * shingle_length)
  in
  if window.end_ - window.start > maximum_window then None
  else begin
    let target =
      normalize_whitespace
        (String.sub contents window.start (window.end_ - window.start))
    in
    match align_normalized normalized_query target.text with
    | None -> None
    | Some aligned ->
        let start, end_ =
          Util.Text.raw_range_of_normalized target ~start:aligned.target.start
            ~end_:aligned.target.end_
        in
        let start = window.start + start in
        let end_ = window.start + end_ in
        let minimum_length = (String.length normalized_query + 1) / 2 in
        if aligned.identical_bytes < minimum_length then None
        else
          Some
            {
              doc_id = meta.doc_id;
              revision = meta.revision;
              contents;
              document_hits = List.length hits;
              num_hits = List.length selected;
              coverage = hit_coverage selected;
              mode_offset;
              window;
              range = { T.start; end_ };
            }
  end

let compare_candidates a b =
  let c = Int.compare b.coverage a.coverage in
  if c <> 0 then c
  else
    let c = Int.compare b.num_hits a.num_hits in
    if c <> 0 then c else compare a.doc_id b.doc_id

let find_candidates db query anchor_norm =
  let query_shingles, by_doc = collect_hits db anchor_norm in
  (* Half the unique query shingles, adjusted for the document stride. *)
  let minimum_hits =
    max 1 ((query_shingles + (2 * shingle_offset) - 1) / (2 * shingle_offset))
  in
  let rejected = ref 0 in
  let candidates =
    Hashtbl.fold
      (fun doc_id hits acc ->
        if List.length hits < minimum_hits then (
          incr rejected;
          acc)
        else
          match DB.Documents.get_full_by_id db doc_id with
          | None ->
              failwith
                (sprintf "anchor relocation error: missing document in db: %s"
                   (App_types.Doc_id.to_string doc_id))
          | Some (_, DB.Deleted) -> acc
          | Some (meta, DB.Active contents) -> (
              match
                align_candidate ~query ~normalized_query:anchor_norm.text meta
                  contents hits
              with
              | None ->
                  incr rejected;
                  acc
              | Some candidate -> candidate :: acc))
      by_doc []
  in
  ( query_shingles,
    minimum_hits,
    !rejected,
    List.sort compare_candidates candidates )

let preview text =
  let len = String.length text in
  if len <= 2048 then text
  else
    String.sub text 0 1024 ^ "\n...[truncated]...\n"
    ^ String.sub text (len - 1024) 1024

(* Log both snapshots before overwriting the anchor. Filtered documents are
   counted in aggregate rather than logged as relocation candidates. *)
let log_relocation_candidates db (a : Internal_types.anchor) ~doc_revision

(* Verify that relocation diagnostics preserve evidence before anchor updates. *)

let source = Option.get (App_types.Source.of_string_opt "files:test")
let src locator = App_types.Src_doc.of_source_doc_exn { source; locator }

let text =
  "The quick brown fox jumps over the lazy dog while a second fox waits \
   patiently nearby watching every single move with great interest today"

let put db path contents =
  fst (Text.add_file db (src path) { Util.Text_source.name = path; contents })

let with_db f =
  Sqlite_util.Connect.with_connection Memory (fun db ->
      Text.create_tables db;
      Text.put_source db source;
      f db)

let capture run =
  Util.Log.with_file ~name:"relocation" run;
  let file =
    Sys.readdir "logs" |> Array.to_list
    |> List.find (String.ends_with ~suffix:"_relocation.log")
  in
  In_channel.with_open_bin (Filename.concat "logs" file) In_channel.input_all

let check_contains data snippets =
  List.iter
    (fun sub ->
      if not (Testo.contains_substring ~sub data) then
        Testo.fail
          (Printf.sprintf "Missing %S in relocation log:\n%s" sub data))
    snippets

let position data sub =
  let rec find i =
    if i + String.length sub > String.length data then
      Testo.fail ("Missing " ^ sub)
    else if String.sub data i (String.length sub) = sub then i
    else find (i + 1)
  in
  find 0

let tests =
  Testo.categorize "relocation logging"
    [
      Testo.create
        "original candidate and stronger destination are inspected before \
         overwrite" (fun () ->
          Testo.with_temp_dir ~chdir:true (fun _ ->
              with_db (fun db ->
                  ignore (put db "original.ml" text);
                  let anchor =
                    Text.add_anchor db (src "original.ml")
                      {
                        Util.Text_source.name = "original.ml";
                        contents = text;
                      }
                      ~expected_revision:0 ~start:0 ~end_:(String.length text)
                  in
                  ignore
                    (put db "destination.ml"
                       ("destination prefix\n" ^ text ^ "\nend"));
                  let data =
                    capture (fun () ->
                        ignore
                          (put db "original.ml"
                             (String.sub text 0 88
                            ^ " unrelated replacement content")))
                  in
                  let relocated =
                    Option.get (Text.get_anchor db anchor.anchor_id)
                  in
                  Testo.check Testo.string "destination.ml"
                    relocated.source_doc.locator;
                  check_contains data
                    [
                      "before mutation";
                      "original_range=B0-";
                      "path=\"original.ml\"";
                      "path=\"destination.ml\"";
                      "matching_hits=";
                      "coverage_bytes=";
                      "coverage_fraction=";
                      "mode_offset=";
                      "predicted_range=B";
                      "effective_range=B";
                      "reason=not selected: lower coverage or tie priority";
                      "greatest matched query coverage";
                      "original_document_best=doc-";
                      "original_document_candidate\n";
                      "selected_destination\n";
                      "would_change_document=true";
                      "ties prefer more inlier hits, then lowest document ID";
                      "minimum_hits=";
                      Printf.sprintf "original_text_preview=%S" text;
                      Printf.sprintf "text_preview=%S" relocated.raw_contents;
                      "applying relocation:";
                    ];
                  Testo.check Testo.bool true
                    (position data "original_document_candidate\n"
                    < position data "applying relocation:");
                  Testo.check Testo.bool true
                    (position data "selected_destination\n"
                    < position data "applying relocation:"))));
      Testo.create
        "a missing original candidate is explicit when the anchor moves"
        (fun () ->
          Testo.with_temp_dir ~chdir:true (fun _ ->
              with_db (fun db ->
                  ignore (put db "original.ml" text);
                  let anchor =
                    Text.add_anchor db (src "original.ml")
                      {
                        Util.Text_source.name = "original.ml";
                        contents = text;
                      }
                      ~expected_revision:0 ~start:0 ~end_:(String.length text)
                  in
                  ignore (put db "destination.ml" text);
                  let data =
                    capture (fun () ->
                        ignore (put db "original.ml" "no match"))
                  in
                  check_contains data
                    [
                      "original_document_candidate=none";
                      "selected_destination\n";
                      "applying relocation:";
                    ];
                  Testo.check Testo.string "destination.ml"
                    (Option.get (Text.get_anchor db anchor.anchor_id))
                      .source_doc
                      .locator)));
      Testo.create
        "failed attempts retain the original anchor and log missing \
         candidates" (fun () ->
          Testo.with_temp_dir ~chdir:true (fun _ ->
              with_db (fun db ->
                  ignore (put db "original.ml" text);
                  let anchor =
                    Text.add_anchor db (src "original.ml")
                      {
                        Util.Text_source.name = "original.ml";
                        contents = text;
                      }
                      ~expected_revision:0 ~start:0 ~end_:(String.length text)
                  in
                  let data =
                    capture (fun () ->
                        ignore (put db "original.ml" "no match"))
                  in
                  check_contains data
                    [
                      "candidates=0";
                      "original_document_candidate=none";
                      "selected_destination=none";
                      Printf.sprintf "original_text_preview=%S" text;
                    ];
                  let unchanged =
                    Option.get (Text.get_anchor db anchor.anchor_id)
                  in
                  Testo.check Testo.string anchor.raw_contents
                    unchanged.raw_contents;
                  Testo.check Testo.bool true (anchor.range = unchanged.range))));
      Testo.create "coverage ties explain the deterministic decision"
        (fun () ->
          Testo.with_temp_dir ~chdir:true (fun _ ->
              with_db (fun db ->
                  ignore (put db "original.ml" text);
                  let anchor =
                    Text.add_anchor db (src "original.ml")
                      {
                        Util.Text_source.name = "original.ml";
                        contents = text;
                      }
                      ~expected_revision:0 ~start:0 ~end_:(String.length text)
                  in
                  ignore (put db "copy.ml" text);
                  let data =
                    capture (fun () ->
                        ignore (put db "original.ml" (text ^ " appended")))
                  in
                  check_contains data
                    [
                      "deterministic tie breaking";
                      "not selected: lower coverage or tie priority";
                      "original_document_preference=none";
                      "original_document_candidate\n";
                      "selected_destination\n";
                      "applying relocation:";
                    ];
                  Testo.check Testo.string text
                    (Option.get (Text.get_anchor db anchor.anchor_id))
                      .raw_contents)));
      Testo.create "a weak document is filtered before candidate logging"
        (fun () ->
          Testo.with_temp_dir ~chdir:true (fun _ ->
              with_db (fun db ->
                  ignore (put db "original.ml" text);
                  let anchor =
                    Text.add_anchor db (src "original.ml")
                      {
                        Util.Text_source.name = "original.ml";
                        contents = text;
                      }
                      ~expected_revision:0 ~start:0 ~end_:(String.length text)
                  in
                  let data =
                    capture (fun () ->
                        ignore
                          (put db "original.ml"
                             (String.sub text 0 16 ^ "UNRELATEDCONTENT")))
                  in
                  check_contains data
                    [
                      "candidates=0 filtered_documents=1";
                      "unique_query_shingles=";
                      "selected_destination=none";
                    ];
                  Testo.check Testo.string text
                    (Option.get (Text.get_anchor db anchor.anchor_id))
                      .raw_contents)));
    ]
